package com.kongye.floatball;
import java.io.*;import java.net.*;import java.security.*;import java.util.*;
public class UpdateTransferCheck {
 static int checks;static void check(boolean b,String s){if(!b)throw new AssertionError(s);checks++;}
 interface Op{void run()throws Exception;}static void reject(Op r,String s)throws Exception{boolean bad=false;try{r.run();}catch(IOException expected){bad=true;}check(bad,s);}
 public static void main(String[] args)throws Exception{
  String good="https://github.com/Mayleaves/KongyeFloat/releases/download/v9/empty.apk";check(UpdateTransfer.assetUrl(good).getHost().equals("github.com"),"own release URL");
  for(String bad:new String[]{"http://github.com/Mayleaves/KongyeFloat/releases/download/v9/a.apk","https://evil.example/a.apk","https://github.com/Other/Repo/releases/download/a.apk","https://github.com.evil.example/Mayleaves/KongyeFloat/releases/download/x/a.apk","https://user@github.com/Mayleaves/KongyeFloat/releases/download/x/a.apk","https://github.com:444/Mayleaves/KongyeFloat/releases/download/x/a.apk","https://github.com/Mayleaves/KongyeFloat/releases/download/../../other.apk","https://github.com/Mayleaves/KongyeFloat/releases/download/%2e%2e/other.apk"})reject(()->UpdateTransfer.assetUrl(bad),"reject wrong asset origin");
  URL base=new URL(good);check(UpdateTransfer.redirect(base,"https://release-assets.githubusercontent.com/release/a.apk?token=demo").getProtocol().equals("https"),"trusted signed redirect");
  for(String bad:new String[]{"http://release-assets.githubusercontent.com/a.apk","https://githubusercontent.com.evil.example/a.apk","https://evilgithubusercontent.com/a.apk","https://user@github.com/x","https://github.com:444/x"})reject(()->UpdateTransfer.redirect(base,bad),"reject unsafe redirect");
  reject(()->UpdateTransfer.redirect(base,null),"missing redirect");byte[] bytes=new byte[350000];new Random(7).nextBytes(bytes);StringBuilder h=new StringBuilder("sha256:");for(byte b:MessageDigest.getInstance("SHA-256").digest(bytes))h.append(String.format("%02x",b&255));ByteArrayOutputStream out=new ByteArrayOutputStream();ArrayList<Long> progress=new ArrayList<>();
  check(UpdateTransfer.copy(new ByteArrayInputStream(bytes),out,bytes.length,h.toString(),()->false,progress::add)==bytes.length,"complete transfer");check(Arrays.equals(bytes,out.toByteArray()),"stream is unchanged");check(progress.get(progress.size()-1)==bytes.length,"final progress reaches size");for(int i=1;i<progress.size();i++)check(progress.get(i)>=progress.get(i-1),"progress monotonic");
  reject(()->UpdateTransfer.copy(new ByteArrayInputStream(bytes),new ByteArrayOutputStream(),bytes.length+1,h.toString(),()->false,x->{}),"truncated stream rejected");reject(()->UpdateTransfer.copy(new ByteArrayInputStream(bytes),new ByteArrayOutputStream(),bytes.length-1,"",()->false,x->{}),"oversized stream rejected");reject(()->UpdateTransfer.copy(new ByteArrayInputStream(new byte[0]),new ByteArrayOutputStream(),0,"",()->false,x->{}),"empty download rejected");
  reject(()->UpdateTransfer.copy(new ByteArrayInputStream(bytes),new ByteArrayOutputStream(),bytes.length,"sha256:"+"0".repeat(64),()->false,x->{}),"checksum mismatch rejected");reject(()->UpdateTransfer.copy(new ByteArrayInputStream(bytes),new ByteArrayOutputStream(),bytes.length,"sha1:bad",()->false,x->{}),"malformed checksum rejected");reject(()->UpdateTransfer.copy(new ByteArrayInputStream(bytes),new ByteArrayOutputStream(),bytes.length,h.toString(),()->true,x->{}),"cancel before copy");
  final boolean[] cancel={false};reject(()->UpdateTransfer.copy(new ByteArrayInputStream(bytes),new ByteArrayOutputStream(),bytes.length,h.toString(),()->cancel[0],x->cancel[0]=true),"cancel mid copy");reject(()->UpdateTransfer.copy(new ByteArrayInputStream(bytes),new ByteArrayOutputStream(),UpdateTransfer.LIMIT+1,"",()->false,x->{}),"download limit");System.out.println(checks+" update transfer checks passed.");
 }
}
